<template><label class="filter-select"><span>{{ label }}</span><select :value="modelValue" @change="change"><option value="">All</option><option v-for="option in options" :key="option.value" :value="option.value">{{ option.value }} ({{ option.count }})</option></select></label></template>
<script setup lang="ts">defineProps<{ modelValue: string; label: string; options: Array<{ value: string; count: number }> }>(); const emit = defineEmits<{ 'update:modelValue': [value: string] }>(); function change(event: Event) { emit('update:modelValue', (event.target as HTMLSelectElement).value) }</script>
<style scoped>.filter-select{display:grid;gap:.4rem}.filter-select span{font-size:.78rem;font-weight:700;color:#475569}.filter-select select{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:.55rem;background:#fff}</style>
